insert into public.content(id,kind,title,description,external_url,status,editorial) values ('ec00c5d9-f2fc-4728-848a-7528ae577f50','event_archive','مروری بر مهم‌ترین نکات کاربردی آیین‌نامه‌ها و مقررات آموزشی تمامی مقاطع تحصیلی','از مجموعه برنامه‌های پژوهشی آغاز سال تحصیلی دانشکدگان فارابی دانشگاه تهران. اطلاعات این صفحه از پوستر رسمی برنامه استخراج شده است.','https://farabi.ut.ac.ir/fa/news/43935','published','{"year":"1403-1404","date":"۵ آذر ۱۴۰۳","time":"۱۲:۴۵ تا ۱۴","speaker":"علی‌اصغر ابراهیمی کوشا","topic":"آموزش","venue":"تالار دکتر کی‌نیا، روبه‌روی سلف غذاخوری خواهران","image":"/assets/official/news-43935-8.webp","order":8,"source":"https://farabi.ut.ac.ir/fa/news/43935"}') on conflict(id) do nothing;
insert into public.content(id,kind,title,description,external_url,status,editorial) values ('4a90b94d-7bf1-4950-83f3-ffbf7681a965','event_archive','آشنایی با آیین‌نامه‌ها و حمایت‌های بنیاد ملی نخبگان','از مجموعه برنامه‌های پژوهشی آغاز سال تحصیلی دانشکدگان فارابی دانشگاه تهران. اطلاعات این صفحه از پوستر رسمی برنامه استخراج شده است.','https://farabi.ut.ac.ir/fa/news/43935','published','{"year":"1403-1404","date":"۶ آذر ۱۴۰۳","time":"۱۲:۴۵ تا ۱۴","speaker":"دکتر سید سعیدرضا منتظری","topic":"حمایت پژوهشی","venue":"تالار دکتر کی‌نیا، روبه‌روی سلف غذاخوری خواهران","image":"/assets/official/news-43935-9.webp","order":9,"source":"https://farabi.ut.ac.ir/fa/news/43935"}') on conflict(id) do nothing;
insert into public.content(id,kind,title,description,external_url,status,editorial) values ('265248d0-3590-4628-8ab1-a0e21f4add13','event_archive','آشنایی با تسهیلات بنیاد ملی نخبگان','از مجموعه برنامه‌های پژوهشی آغاز سال تحصیلی دانشکدگان فارابی دانشگاه تهران. اطلاعات این صفحه از پوستر رسمی برنامه استخراج شده است.','https://farabi.ut.ac.ir/fa/news/50799','published','{"year":"1404-1405","date":"۲۰ آبان ۱۴۰۴","time":"۱۰:۴۵ تا ۱۲","speaker":"دکتر سید سعیدرضا منتظری","topic":"حمایت پژوهشی","venue":"تالار دکتر الوانی، طبقه همکف دانشکده مدیریت","image":"/assets/official/news-50799-1.webp","order":1,"source":"https://farabi.ut.ac.ir/fa/news/50799"}') on conflict(id) do nothing;
